#!/usr/bin/env python3
"""Hyperbolic-geodesic and Ryu-Takayanagi bridge of history interval space."""
import json,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];sys.path.insert(0,str(ROOT/'research/benincasa/.tmp_sympy'));import sympy as s
x,R,dx,dR,c,eps=s.symbols('x R dx dR c eps',positive=True);u=x-R;v=x+R;du=dx-dR;dv=dx+dR;interval_metric=s.expand(4*du*dv/(v-u)**2);planar_metric=(dx**2-dR**2)/R**2;Lreg=2*s.log((v-u)/eps);Srt=c/s.Integer(6)*Lreg;Sent=c/s.Integer(3)*s.log((v-u)/eps);checks={'endpoint_metric_becomes_planar_desitter':s.simplify(interval_metric-planar_metric)==0,'geodesic_center_is_midpoint':s.simplify((u+v)/2-x)==0,'geodesic_radius_is_half_interval':s.simplify((v-u)/2-R)==0,'rt_entropy_equals_interval_entropy':s.simplify(Srt-Sent)==0,'geodesic_length_is_logarithmic':s.simplify(Lreg-2*s.log(2*R/eps))==0}
out={'schema':'marici.nima.nnmhv-hyperbolic-geodesic-rt-bridge.v1','hyperbolic_space':'upper-half-plane H^2 with boundary endpoints u<v','oriented_geodesic':'semicircle center x=(u+v)/2 and radius R=(v-u)/2','kinematic_metric':'ds^2=(dx^2-dR^2)/R^2 = 4 du dv/(v-u)^2','regulated_length':'L_gamma=2 log((v-u)/epsilon)','rt_relation':'S=(c/6)L_gamma=(c/3)log((v-u)/epsilon)','checks':checks,'passed':all(checks.values()),'meaning':'Each continuum history interval is equivalently an oriented hyperbolic geodesic. History interval space is its de Sitter kinematic space, and the entropy potential generating the metric is the regulated geodesic length.','bridges':['space of oriented geodesics of H^2','AdS3/CFT2 time-slice kinematic space','Ryu-Takayanagi entropy-length relation','Crofton reconstruction','scale R as de Sitter time']};p=ROOT/'research/nima/results/nnmhv-hyperbolic-geodesic-rt-bridge.json';p.write_text(json.dumps(out,indent=2)+'\n');print(json.dumps(out,indent=2));raise SystemExit(0 if out['passed'] else 1)
